#!/bin/bash

# Get the current git commit hash (short version)
GIT_HASH=$(git rev-parse --short=7 HEAD 2>/dev/null || echo "dev")

# Path to the Swift file
SWIFT_FILE="${SRCROOT}/Cue Bear/Cue Bear/GitCommitHash.swift"

# Path to the changelog file
CHANGELOG_FILE="${SRCROOT}/CHANGELOG.md"

# Create the Swift file content
cat > "$SWIFT_FILE" << EOF
// This file is auto-generated by the build script
// DO NOT EDIT MANUALLY

import Foundation

enum GitInfo {
    static let commitHash = "$GIT_HASH"
}
EOF

echo "✅ Updated GitCommitHash.swift with commit: $GIT_HASH"

# Generate changelog from git history
if [ -d ".git" ]; then
    echo "📝 Generating changelog..."

    # Get all commits with their messages
    cat > "$CHANGELOG_FILE" << 'HEADER'
# Cue Bear - Changelog

This changelog is automatically generated from git commits.

---

HEADER

    # Get commit history formatted nicely
    git log --pretty=format:"## %h - %s%n%n**Date:** %ad%n**Author:** %an%n%n%b%n----%n" --date=short >> "$CHANGELOG_FILE"

    echo "✅ Generated changelog with $(git rev-list --count HEAD) commits"
else
    echo "⚠️  Not a git repository, skipping changelog generation"
fi
